    list_grants: {
        parameters: {
            query?: {
                /** @description Normalized status, exact match: `open` | `forecasted` | `closed`. */
                status?: string | null;
                /** @description Case-insensitive substring of the agency name (e.g. `health`). */
                agency?: string | null;
                /** @description Source app, exact match: `grants-gov` | `ca-grants` | `eu-sedia`. */
                source?: string | null;
                /**
                 * @description Funding-program key, exact match — the `program_key` of `GET
                 *     /grants/programs` (`aln:93.912`, `family:HORIZON-CL4-DATA-01`,
                 *     `<agency>|<program title>`). Every posting of one program, across cycles
                 *     and portals, in one query. Rows the identity rules could not name a
                 *     program for carry no `program_key` and never match.
                 */
                program?: string | null;
                /** @description Closes on or before this `YYYY-MM-DD`. Records with no close date are excluded. */
                closing_before?: string | null;
                /** @description Closes on or after this `YYYY-MM-DD`. Records with no close date are excluded. */
                closing_after?: string | null;
                /** @description Minimum money: keeps records whose `award_ceiling` OR `total_funding` is >= this. */
                min_award?: number | null;
                /**
                 * @description Trust filter over the shared corpus: `all` (default — every record carries
                 *     its own `trust` field), `stable`, `provisional` or `quarantined`.
                 *
                 *     `grants/unified` is written by three independent sources, and each run's
                 *     contribution is stamped with THAT source's extraction health
                 *     (`grants_common::contribution_target`): a degrading source's rows land here
                 *     stamped `provisional`, a quarantined source's are diverted out to
                 *     `grants/unified@q` entirely. `trust=stable` is how a consumer asks for only
                 *     the rows we stand behind — the same vocabulary as `/datasets` and `/changes`.
                 */
                trust?: string;
                limit?: number;
                /** @description Opaque keyset cursor; presence (even empty) switches to `{items, next_cursor}`. */
                cursor?: string | null;
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Live records from `grants/unified` matching every filter, newest-updated first. Dual-mode: `{grants: [Record]}`, or `{items, next_cursor}` when `cursor` is present (even empty). */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["GrantsResponse"];
                };
            };
            /** @description Malformed `closing_before` / `closing_after` date */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorEnvelope"];
                };
            };
        };
    };
    closing_soon: {
        parameters: {
            query?: {
                /** @description Window size in days from today. Default 14, clamped to 1..=365. */
                days?: number | null;
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description `{days, count, grants}` — live open grants closing within the window, soonest first. Each grant is its unified record `data` plus `key` and `days_left`. `count` is the window total; `grants` is capped at 200. "Still open" is decided at `deadline_end_utc` — the exact `close_at` instant, or midday UTC the day after a date-only `close_date` — so a grant in that anywhere-on-Earth tail is listed with `days_left: 0`, exactly as `grants/unified` still calls it `open`. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ClosingSoonResponse"];
                };
            };
        };
    };
