    search: {
        parameters: {
            query: {
                q: string;
                limit?: number;
                /** @description Restrict hits to one app. */
                app?: string | null;
                /** @description Restrict hits to one dataset. */
                dataset?: string | null;
                /** @description Typo tolerance (edit distance 1). Quoted phrases stay exact. */
                fuzzy?: boolean;
                /** @description Ordering: `score` (relevance, default) or `newest` (most recently indexed). */
                sort?: string | null;
                /** @description Only hits indexed at/after this unix-seconds instant (a "what's new" feed). */
                since?: number | null;
                /** @description Skip this many ranked hits before `limit` (page 2 = `offset=limit`). Capped. */
                offset?: number | null;
                /**
                 * @description Only hits whose index-time-extracted money amount (whole US dollars) is
                 *     >= this. Docs where no amount was extracted never match.
                 */
                amount_gte?: number | null;
                /** @description Only hits whose extracted amount is <= this (whole US dollars). */
                amount_lte?: number | null;
                /**
                 * @description Only hits whose extracted deadline (`event_date`, unix seconds) is
                 *     at/after this. Docs with no extracted deadline never match.
                 */
                date_after?: number | null;
                /** @description Only hits whose extracted deadline is at/before this (unix seconds). */
                date_before?: number | null;
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description `{query, total, count, hits, facets, index}` — BM25 ranked (or `sort=newest`), highlighted snippets. `total` is the full match count; `count` is the returned page size. `offset` pages (offset=limit → page 2, clamped to 10000); `sort=newest` orders by index time; `since=<unix-secs>` filters to recent docs. Entity filters (index-time regex extraction; docs without an extracted value never match): `amount_gte`/`amount_lte` in whole US dollars, `date_before`/`date_after` on the extracted deadline (unix seconds). The MCP `search` tool takes these same params through the same parser, and returns everything but `facets`. `index` is the state the answer was computed against — `{enabled, doc_count, degraded, reason}`; `degraded: true` (disabled index, or an enabled one holding 0 documents) means an empty page is NOT evidence the records are missing, and `reason` names the recovery. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["SearchResponse"];
                };
            };
            /** @description Empty query, or a `sort` other than `score`/`newest` */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorEnvelope"];
                };
            };
        };
    };
